{"code": "import json
from datetime import datetime, timezone

path = "/home/bob/.hermes/.openclaw/workspace/memory/agent-communications.jsonl"
now_dt = datetime.now(timezone.utc)

with open(path) as f:
    lines = [l.strip() for l in f if l.strip()]
entries = [json.loads(l) for l in lines]

updated = 0
for entry in entries:
    if entry.get("status") == "pending":
        try:
            ts = entry["timestamp"]
            entry_dt = datetime.fromisoformat(ts.replace("Z", "+00:00"))
            days_old = (now_dt - entry_dt).days

            # Check if past deadline too
            deadline_str = entry.get("payload", {}).get("deadline", "")
            past_deadline = False
            if deadline_str:
                try:
                    deadline_dt = datetime.fromisoformat(deadline_str.replace("Z", "+00:00"))
                    past_deadline = now_dt > deadline_dt
                except:
                    pass

            if past_deadline and days_old >= 3:
                entry["status"] = "overdue"
                entry["original_status"] = "pending"
                updated += 1
                print(f"✓ Set {entry['task_id']} to 'overdue' (pending {days_old}d, past deadline)")
        except Exception as e:
            print(f"  Error with {entry['task_id']}: {e}")

with open(path, 'w') as f:
    for entry in entries:
        f.write(json.dumps(entry, ensure_ascii=False) + '\n')

statuses = {}
for e in entries:
    s = e.get("status", "unknown")
    statuses[s] = statuses.get(s, 0) + 1
print(f"\nAfter update: {statuses}")
print(f"Updated {updated} tasks to 'overdue'")
"}

